'use client'

import { useEffect, useMemo, useState } from 'react'
import QRCode from 'qrcode'
import { Check, ChevronDown, ChevronRight, Plus, X } from 'lucide-react'

type ProductType = 'Marine cargo' | 'Motor fleet' | 'Property' | 'SME package' | 'Takaful'
type DeliveryMethod = 'Embedded widget' | 'Bank / partner API'
type Coverage = { id: string; name: string; description: string; enabled: boolean; limit?: string; deductible?: string; conditions?: string; pricing?: string; pricingMethod?: 'included' | 'rate' | 'flat' | 'percent' | 'per-unit' | 'manual'; pricingValue?: string; pricingUnit?: string }

const productTypes: { name: ProductType; description: string; example: string }[] = [
  { name: 'Marine cargo', description: 'Protect goods while moving through ports, roads, and borders.', example: 'Imports, exports, transit, and local delivery' },
]

const coverageSets: Record<ProductType, Coverage[]> = {
  'Marine cargo': [
    { id: 'damage', name: 'Cargo damage', description: 'All-risk physical loss or damage in transit', enabled: true },
    { id: 'theft', name: 'Theft and non-delivery', description: 'Theft, pilferage, or missing cargo', enabled: true },
    { id: 'water', name: 'Water damage', description: 'Wet damage, contamination, or seawater ingress', enabled: false },
    { id: 'war', name: 'War and strikes', description: 'War, strikes, civil commotion, and riots', enabled: false },
  ],
  'Motor fleet': [
    { id: 'third-party', name: 'Third-party liability', description: 'Mandatory liability for damage to others', enabled: true },
    { id: 'own-damage', name: 'Own vehicle damage', description: 'Collision, overturning, and accidental damage', enabled: true },
    { id: 'theft', name: 'Theft and fire', description: 'Vehicle theft, fire, and attempted theft', enabled: false },
    { id: 'personal-accident', name: 'Driver personal accident', description: 'Accidental injury benefit for drivers', enabled: false },
  ],
  Property: [
    { id: 'fire', name: 'Fire and explosion', description: 'Fire, lightning, and explosion damage', enabled: true },
    { id: 'theft', name: 'Burglary and theft', description: 'Loss following forcible entry', enabled: true },
    { id: 'water', name: 'Water and weather', description: 'Storm, flood, burst pipes, and water damage', enabled: false },
    { id: 'business-interruption', name: 'Business interruption', description: 'Lost income after an insured event', enabled: false },
  ],
  'SME package': [
    { id: 'property', name: 'Business property', description: 'Premises, stock, equipment, and contents', enabled: true },
    { id: 'liability', name: 'Public liability', description: 'Third-party injury and property damage', enabled: true },
    { id: 'money', name: 'Money and cash', description: 'Cash in premises or in transit', enabled: false },
    { id: 'employee', name: 'Employee accident', description: 'Accidental injury benefit for employees', enabled: false },
  ],
  Takaful: [
    { id: 'protection', name: 'Core protection', description: 'The selected asset or activity protection', enabled: true },
    { id: 'third-party', name: 'Third-party liability', description: 'Liability protection within the approved structure', enabled: false },
    { id: 'surplus', name: 'Surplus participation', description: 'Define the participant surplus treatment', enabled: true },
    { id: 'assistance', name: 'Assistance benefit', description: 'Optional assistance or recovery service', enabled: false },
  ],
}

const pricingPresets: Record<ProductType, { basis: string; options: string[]; inputLabel: string; previewLabel: string; help: string; defaultRate: string }> = {
  'Marine cargo': { basis: 'Cargo value', options: ['Cargo value', 'Per shipment', 'Flat premium', 'Manual quote'], inputLabel: 'Rate per 100 LYD', previewLabel: 'Insured cargo value', help: 'Charge a percentage of the declared cargo value, with optional minimums and route loadings.', defaultRate: '0.35' },
  'Motor fleet': { basis: 'Per vehicle', options: ['Per vehicle', 'Per vehicle value', 'Fleet schedule', 'Manual quote'], inputLabel: 'Premium per vehicle', previewLabel: 'Number of vehicles', help: 'Price by vehicle, vehicle value, or a fleet schedule with volume discounts.', defaultRate: '850' },
  Property: { basis: 'Property value', options: ['Property value', 'Flat premium', 'Per location', 'Manual quote'], inputLabel: 'Rate per 100 LYD', previewLabel: 'Insured property value', help: 'Price against buildings, contents, stock, or each insured location.', defaultRate: '0.22' },
  'SME package': { basis: 'Package premium', options: ['Package premium', 'Business turnover', 'Per location', 'Manual quote'], inputLabel: 'Package premium', previewLabel: 'Annual turnover', help: 'Combine covers into one package premium or vary it by turnover and locations.', defaultRate: '2400' },
  Takaful: { basis: 'Contribution value', options: ['Contribution value', 'Flat contribution', 'Per participant', 'Manual quote'], inputLabel: 'Contribution rate', previewLabel: 'Protected value', help: 'Set participant contributions, fees, and the surplus treatment for this structure.', defaultRate: '0.30' },
}

const limitPresets: Record<ProductType, { title: string; limitLabel: string; deductibleLabel: string; unit: string; helper: string; extra: string[] }> = {
  'Marine cargo': { title: 'Cargo limits and deductibles', limitLabel: 'Maximum cargo value per shipment', deductibleLabel: 'Cargo deductible', unit: 'LYD', helper: 'Set the largest declared value you will accept for one shipment and the amount the customer retains on each loss.', extra: ['Maximum accumulation at port', 'Maximum transit duration'] },
  'Motor fleet': { title: 'Fleet limits and deductibles', limitLabel: 'Maximum vehicle value', deductibleLabel: 'Vehicle damage deductible', unit: 'LYD', helper: 'Set vehicle value limits, liability limits, and the customer contribution for each claim.', extra: ['Third-party liability limit', 'Maximum fleet size'] },
  Property: { title: 'Property limits and deductibles', limitLabel: 'Maximum property value per location', deductibleLabel: 'Property deductible', unit: 'LYD', helper: 'Set the value accepted at each site and the customer contribution for fire, theft, and weather claims.', extra: ['Contents / stock limit', 'Business interruption limit'] },
  'SME package': { title: 'Business package limits', limitLabel: 'Maximum business asset value', deductibleLabel: 'Standard package deductible', unit: 'LYD', helper: 'Set practical limits for the business package and let each included cover have its own sub-limit.', extra: ['Public liability limit', 'Employee accident limit'] },
  Takaful: { title: 'Protection limits and participant share', limitLabel: 'Maximum protected value', deductibleLabel: 'Participant contribution', unit: 'LYD', helper: 'Set the protected value and participant share while keeping the contribution structure transparent.', extra: ['Surplus pool limit', 'Assistance benefit limit'] },
}

const conditionPresets: Record<ProductType, { title: string; helper: string; sections: { title: string; text: string }[] }> = {
  'Marine cargo': { title: 'Transit conditions', helper: 'Set the route, cargo, and transit rules that must be clear before a shipment can be quoted.', sections: [{ title: 'Eligible cargo and goods', text: 'Define commodity classes, packing standards, and goods you will accept.' }, { title: 'Transit and route rules', text: 'Set origin, destination, ports, storage days, and approved transport routes.' }, { title: 'Exclusions and warranties', text: 'Add plain-language exclusions for fragile goods, poor packing, delay, or unattended storage.' }, { title: 'Claims and documents', text: 'Specify invoice, packing list, bill of lading, survey, and notification requirements.' }] },
  'Motor fleet': { title: 'Driver conditions', helper: 'Define who may drive, how vehicles are used, and what evidence is needed after an accident.', sections: [{ title: 'Approved drivers', text: 'Set licence class, driver age, experience, and named-driver requirements.' }, { title: 'Vehicle use and territory', text: 'Define commercial use, territory, overnight parking, and permitted vehicle classes.' }, { title: 'Safety and maintenance', text: 'Require inspections, tracking devices, maintenance records, or anti-theft measures.' }, { title: 'Accident and claims steps', text: 'Set accident notification timing, police reports, photos, and repair approval rules.' }] },
  Property: { title: 'Site conditions', helper: 'Define the building, occupancy, protection systems, and events that qualify for cover.', sections: [{ title: 'Eligible premises', text: 'Set building construction, occupancy, location, and acceptable business activities.' }, { title: 'Protection requirements', text: 'Require alarms, fire extinguishers, guards, sprinklers, or electrical inspections.' }, { title: 'Events and exclusions', text: 'Define fire, theft, weather, flood, vacancy, maintenance, and unoccupied-period rules.' }, { title: 'Valuation and claims', text: 'Set replacement value, stock records, proof of ownership, and loss notification steps.' }] },
  'SME package': { title: 'Business conditions', helper: 'Make each package suitable for the size, activity, and operating profile of the business.', sections: [{ title: 'Eligible businesses', text: 'Define sectors, annual turnover, employee count, and approved business activities.' }, { title: 'Package requirements', text: 'Choose which covers are required together and set any cover-specific conditions.' }, { title: 'Risk controls', text: 'Require premises security, cash handling, workplace safety, or equipment records.' }, { title: 'Documents and claims', text: 'Request registration, inventory, payroll, incident reports, and supporting evidence.' }] },
  Takaful: { title: 'Takaful rules', helper: 'Explain the participant, fund, contribution, and surplus rules in a clear and Sharia-aligned way.', sections: [{ title: 'Approved activities and assets', text: 'Define the permissible business, asset, or activity that may participate.' }, { title: 'Participant obligations', text: 'Set disclosure, contribution, cooperation, and risk-prevention responsibilities.' }, { title: 'Excluded activities', text: 'List prohibited or excluded activities, goods, income sources, and circumstances.' }, { title: 'Fund and surplus treatment', text: 'Explain wakala fee, risk fund treatment, claims support, and surplus participation.' }] },
}

const policyFieldPresets: Record<ProductType, string[]> = {
  'Marine cargo': ['Assured name', 'National ID / company registration', 'Cargo description', 'HS code', 'Product type', 'Commodity value', 'Invoice number', 'Origin and destination', 'Transport mode', 'Vessel / voyage details', 'Packing details', 'Bill of lading number', 'Port storage days', 'Effective dates', 'Beneficiary details'],
  'Motor fleet': ['Policyholder name', 'National ID / company registration', 'Vehicle plate number', 'Chassis / VIN', 'Make and model', 'Vehicle use', 'Driver name and licence', 'Vehicle value', 'Territory', 'Effective dates', 'Beneficiary details'],
  Property: ['Policyholder name', 'National ID / company registration', 'Property address', 'Occupancy / business activity', 'Building value', 'Contents and stock value', 'Construction type', 'Protection systems', 'Loss history', 'Effective dates', 'Mortgagee / beneficiary details'],
  'SME package': ['Business name', 'Commercial registration', 'Business activity', 'Business address', 'Annual turnover', 'Employee count', 'Building and contents values', 'Selected covers', 'Loss history', 'Effective dates', 'Beneficiary details'],
  Takaful: ['Participant name', 'National ID / company registration', 'Protected activity or asset', 'Contribution basis', 'Protected value', 'Participant declaration', 'Beneficiary details', 'Fund and surplus acknowledgement', 'Effective dates'],
}

const stepLabels: Record<ProductType, string[]> = {
  'Marine cargo': ['Product type', 'Cargo cover', 'Limits & deductibles', 'Cargo pricing', 'Transit conditions', 'Questions', 'Quote preview', 'Publish'],
  'Motor fleet': ['Product type', 'Vehicle cover', 'Fleet limits', 'Fleet pricing', 'Driver conditions', 'Questions', 'Quote preview', 'Publish'],
  Property: ['Product type', 'Property cover', 'Property limits', 'Property pricing', 'Site conditions', 'Questions', 'Quote preview', 'Publish'],
  'SME package': ['Product type', 'Package covers', 'Business limits', 'Package pricing', 'Business conditions', 'Questions', 'Quote preview', 'Publish'],
  Takaful: ['Product type', 'Approved covers', 'Protection limits', 'Contribution pricing', 'Takaful rules', 'Questions', 'Quote preview', 'Publish'],
}

export function ProductFactory({ onClose }: { onClose?: () => void }) {
  const [step, setStep] = useState('Product type')
  const [productType, setProductType] = useState<ProductType>('Marine cargo')
  const [deliveryMethod, setDeliveryMethod] = useState<DeliveryMethod>('Embedded widget')
  const [productName, setProductName] = useState('Libya Cargo Protect')
  const [coverages, setCoverages] = useState(coverageSets['Marine cargo'])
  const [baseRate, setBaseRate] = useState('0.35')
  const [minimumPremium, setMinimumPremium] = useState('50')
  const [deductible, setDeductible] = useState('5000')
  const [limit, setLimit] = useState('1000000')
  const [pricingBasis, setPricingBasis] = useState('Cargo value')
  const [pricingMode, setPricingMode] = useState<'rate' | 'tiers' | 'formula' | 'manual'>('rate')
  const [tierRows, setTierRows] = useState([['Up to 500,000', '0.35'], ['500,001 – 2,000,000', '0.28'], ['Above 2,000,000', '0.22']])
  const [loading, setLoading] = useState('0')
  const [serviceFee, setServiceFee] = useState('0')
  const [tax, setTax] = useState('0')
  const [lisaFee, setLisaFee] = useState('0')
  const [underwritingFee, setUnderwritingFee] = useState('0')
  const [feeMode, setFeeMode] = useState<'percentage' | 'fixed'>('percentage')
  const [currency, setCurrency] = useState('LYD')
  const [previewValue, setPreviewValue] = useState('750000')
  const [saved, setSaved] = useState(false)
  const [productCode, setProductCode] = useState('')
  const [version, setVersion] = useState('1.0')
  const [changeNote, setChangeNote] = useState('')
  const [approvalRequired, setApprovalRequired] = useState(true)
  const [coverDraft, setCoverDraft] = useState<Coverage | null>(null)
  const [conditionSections, setConditionSections] = useState(conditionPresets['Marine cargo'].sections)
  const [conditionDraft, setConditionDraft] = useState<{ title: string; text: string } | null>(null)
  const [questions, setQuestions] = useState<string[]>(productType === 'Marine cargo' ? ['What is being shipped?', 'What is the cargo value?', 'What are the origin and destination?'] : [])
  const [effectiveDate, setEffectiveDate] = useState('')
  const [referralThreshold, setReferralThreshold] = useState('')
  const [underwritingRequired, setUnderwritingRequired] = useState(true)
  const [insurerName, setInsurerName] = useState('')
  const [logoUrl, setLogoUrl] = useState('')
  const [arabicWording, setArabicWording] = useState('')
  const [englishWording, setEnglishWording] = useState('')
  const [policyTerms, setPolicyTerms] = useState('')
  const [policyFields, setPolicyFields] = useState(policyFieldPresets['Marine cargo'])
  const [partnerBranding, setPartnerBranding] = useState(false)
  const [policyQr, setPolicyQr] = useState('')
  const verificationReference = productName.trim() ? `DRAFT-${productType.replace(/[^A-Z0-9]/gi, '').toUpperCase()}-${productName.trim().replace(/[^A-Z0-9]/gi, '').slice(0, 10).toUpperCase()}` : 'DRAFT-POLICY'
  const verificationUrl = typeof window !== 'undefined' ? `${window.location.origin}/verify/policy/${verificationReference}` : `/verify/policy/${verificationReference}`
  useEffect(() => { QRCode.toDataURL(verificationUrl, { width: 132, margin: 1, color: { dark: '#193332', light: '#ffffff' } }).then(setPolicyQr).catch(() => setPolicyQr('')) }, [verificationUrl])
  const [riskRules, setRiskRules] = useState([{ name: 'High-risk cargo loading', trigger: 'Cargo class is dangerous goods, electronics, pharmaceuticals, temperature-controlled, or high-theft goods', adjustment: '0.50', unit: 'rate points', enabled: false }, { name: 'War and strikes loading', trigger: 'Transit includes an approved high-risk territory or war-risk route', adjustment: '0.75', unit: 'rate points', enabled: false }, { name: 'Port storage loading', trigger: 'Cargo remains at port longer than the included storage period', adjustment: '15', unit: 'percent', enabled: false }])
  const [editingRiskRule, setEditingRiskRule] = useState<number | null>(null)
  const [cargoClass, setCargoClass] = useState('General cargo')
  const [routeProfile, setRouteProfile] = useState('Standard approved route')
  const [storageDays, setStorageDays] = useState('3')

  const enabledCoverages = coverages.filter((coverage) => coverage.enabled)
  const previewNumber = Number(previewValue) || 0
  const tierRate = tierRows.find((row, index) => index === 0 ? previewNumber <= 500000 : index === 1 ? previewNumber <= 2000000 : previewNumber > 2000000)?.[1] || baseRate
  const selectedRate = pricingMode === 'tiers' ? Number(tierRate) || 0 : Number(baseRate) || 0
  const detectedHighRisk = productType === 'Marine cargo' && (['Dangerous goods', 'Electronics', 'Pharmaceuticals', 'Temperature-controlled', 'High-theft goods'].includes(cargoClass) || routeProfile === 'High-risk / war-risk route' || Number(storageDays) > 7)
  const detectedRiskTypes = productType === 'Marine cargo' ? [(['Dangerous goods', 'Electronics', 'Pharmaceuticals', 'Temperature-controlled', 'High-theft goods'].includes(cargoClass) ? 'Cargo class loading' : ''), routeProfile === 'High-risk / war-risk route' ? 'War and route loading' : '', Number(storageDays) > 7 ? 'Port storage loading' : ''].filter(Boolean) : []
  const matchingRiskRule = (rule: { name: string }) => !detectedHighRisk || rule.name === 'High-risk cargo loading' || (routeProfile === 'High-risk / war-risk route' && rule.name === 'War and strikes loading') || (Number(storageDays) > 7 && rule.name === 'Port storage loading')
  const activeRiskRate = productType === 'Marine cargo' ? riskRules.filter(rule => rule.enabled && matchingRiskRule(rule) && rule.unit === 'rate points').reduce((total, rule) => total + (Number(rule.adjustment) || 0), 0) : 0
  const activeRiskPercent = productType === 'Marine cargo' ? riskRules.filter(rule => rule.enabled && matchingRiskRule(rule) && rule.unit === 'percent').reduce((total, rule) => total + (Number(rule.adjustment) || 0), 0) : 0
  const premiumBase = pricingMode === 'manual' ? 0 : pricingBasis === 'Per vehicle' || pricingBasis === 'Per location' || pricingBasis === 'Per participant' ? previewNumber * selectedRate : pricingBasis === 'Flat premium' || pricingBasis === 'Package premium' || pricingBasis === 'Flat contribution' ? selectedRate : previewNumber * selectedRate / 100
  const subtotal = Math.max(Number(minimumPremium) || 0, Math.round(premiumBase))
  const lisaAmount = feeMode === 'percentage' ? subtotal * (Number(lisaFee) || 0) / 100 : Number(lisaFee) || 0
  const underwritingAmount = feeMode === 'percentage' ? subtotal * (Number(underwritingFee) || 0) / 100 : Number(underwritingFee) || 0
  const riskAmount = pricingMode === 'manual' ? 0 : Math.round((pricingBasis.includes('value') ? previewNumber * activeRiskRate / 100 : activeRiskRate) + subtotal * activeRiskPercent / 100)
  const premium = pricingMode === 'manual' ? 0 : Math.round(subtotal + riskAmount + lisaAmount + underwritingAmount + subtotal * ((Number(loading) || 0) + (Number(serviceFee) || 0) + (Number(tax) || 0)) / 100)
  const selectedType = productTypes.find((type) => type.name === productType)!
  const pricingConfig = pricingPresets[productType]
  const limitConfig = limitPresets[productType]
  const currentSteps = stepLabels[productType]
  const validationIssues = [
    !productName.trim() ? 'Add a product name.' : '',
    !productCode.trim() ? 'Add a unique product code.' : '',
    enabledCoverages.length === 0 ? 'Enable at least one cover.' : '',
    !policyTerms.trim() ? 'Add binding policy terms.' : '',
    !effectiveDate ? 'Set an effective date.' : '',
    pricingMode !== 'manual' && Number(baseRate) <= 0 ? 'Set a valid base rate.' : '',
    deliveryMethod === 'Bank / partner API' && !insurerName.trim() ? 'Add the insurer display name for API policy documents.' : '',
  ].filter(Boolean)
  const canPublish = validationIssues.length === 0
  const stepIndex = Math.max(0, currentSteps.findIndex((label) => label === step))
  const selectProductType = (type: ProductType) => { setProductType(type); setPolicyFields(policyFieldPresets[type]); setCoverages(coverageSets[type]); setQuestions(type === 'Marine cargo' ? ['What is being shipped?', 'What is the cargo value?', 'What are the origin and destination?'] : type === 'Motor fleet' ? ['How many vehicles are insured?', 'What is the vehicle use?', 'Who are the drivers?'] : type === 'Property' ? ['What is the property used for?', 'Where is it located?', 'What are the building and contents values?'] : type === 'SME package' ? ['What does the business do?', 'What is the annual turnover?', 'How many employees are covered?'] : ['What activity or asset is being protected?', 'What is the protected value?', 'How will contributions and surplus be handled?']); setConditionSections(conditionPresets[type].sections); setPricingBasis(pricingPresets[type].basis); setPricingMode('rate'); setBaseRate(pricingPresets[type].defaultRate); setLimit(type === 'Motor fleet' ? '150000' : type === 'Property' ? '5000000' : type === 'SME package' ? '2500000' : '1000000'); setDeductible(type === 'Motor fleet' ? '2500' : type === 'Takaful' ? '1000' : '5000'); setPreviewValue(type === 'Motor fleet' ? '10' : type === 'SME package' ? '2500000' : '750000'); setStep('Product type'); setSaved(false) }

  const updateCoverage = (id: string, enabled: boolean) => setCoverages((current) => current.map((coverage) => coverage.id === id ? { ...coverage, enabled } : coverage))
  const openCoverageEditor = (coverage: Coverage) => { setCoverDraft({ ...coverage }) }
  const saveCoverage = () => { if (!coverDraft) return; setCoverages((current) => current.map((coverage) => coverage.id === coverDraft.id ? coverDraft : coverage)); setCoverDraft(null) }
  const addCoverage = () => { const coverage = { id: `custom-${Date.now()}`, name: 'New optional cover', description: '', enabled: false, limit: '', deductible: '', conditions: '', pricing: '' }; setCoverages((current) => [...current, coverage]); openCoverageEditor(coverage) }

  return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#f2f7f5] text-[#193332]">
    <header className="sticky top-0 z-20 flex min-h-[68px] items-center justify-between border-b border-[#dbe8e4] bg-white px-4 sm:px-7">
      <div className="flex items-center gap-3"><button onClick={onClose} className="rounded-lg border border-[#dfe9e7] p-2 text-[#586970]" aria-label="Close builder"><X size={16}/></button><div><div className="flex items-center gap-2"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#00392F]">Product builder / draft</p><span className="rounded-full bg-[#f2f6f5] px-2 py-1 text-[9px] font-semibold text-[#586970]">v{version}</span></div><h1 className="text-base font-semibold">{productName || 'Untitled product'}</h1><p className="text-[10px] text-[#91a5a2]">{saved ? 'Saved just now' : 'Unsaved changes'}{productCode ? ` · ${productCode}` : ''}</p></div></div>
      <div className="flex gap-2"><button onClick={() => setSaved(true)} className="rounded-lg border border-[#b9d9d2] px-3 py-2 text-[11px] font-semibold text-[#00392F]">Save draft</button><button onClick={() => setStep(currentSteps[6])} className="rounded-lg border border-[#b9d9d2] px-3 py-2 text-[11px] font-semibold text-[#00392F]">Preview</button><button onClick={() => { setStep(currentSteps[7]); if (canPublish) setSaved(true) }} className="rounded-lg bg-[#00392F] px-3 py-2 text-[11px] font-semibold text-white">Publish</button></div>
    </header>
    <div className="mx-auto w-full max-w-[1600px]"><div className="grid items-start lg:grid-cols-[200px_minmax(0,1fr)_280px]">
      <aside className="hidden border-b border-[#dbe8e4] bg-[#f8fbfa] p-3 lg:block lg:min-h-[calc(100vh-68px)] lg:border-r"><p className="px-2 pb-1 text-[10px] font-bold uppercase tracking-[.16em] text-[#91a5a2]">Build your product</p><p className="px-2 pb-3 text-[10px] leading-4 text-[#78908d]">Move through each section in order. You can revisit completed steps anytime.</p>{currentSteps.map((item, index) => <button key={item} onClick={() => setStep(item)} className={`flex w-full items-center gap-2 rounded-lg px-2 py-2 text-left text-[11px] ${step === item ? 'bg-[#dff1ec] font-semibold text-[#00392F]' : 'text-[#66817c]'}`}><span className={`flex size-5 items-center justify-center rounded-full text-[9px] ${index < stepIndex ? 'bg-[#00392F] text-white' : step === item ? 'bg-[#57D8FF] text-[#00392F]' : 'bg-white text-[#586970]'}`}>{index < stepIndex ? '✓' : index + 1}</span><span className="min-w-0 flex-1">{item}</span>{step === item && <span className="text-[9px] font-bold uppercase tracking-[.08em] text-[#00392F]">Current</span>}</button>)}</aside>
      <main className="min-w-0 px-4 py-4 sm:px-6 sm:py-5 lg:col-start-2 lg:row-start-1"><div className="mx-auto w-full max-w-[820px]"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#00392F]">Step {stepIndex + 1} of {currentSteps.length}</p><h2 className="mt-1 text-xl font-semibold tracking-[-.03em] sm:text-2xl">{stepIndex === 0 ? 'Start with the product you want to sell' : stepIndex === 1 ? 'Choose what the product protects' : stepIndex === 2 ? 'Set the protection boundaries' : stepIndex === 3 ? 'Choose how customers are charged' : stepIndex === 4 ? 'Add the rules that keep the product clear' : stepIndex === 6 ? 'See exactly what customers will receive' : step}</h2><p className="mt-1 max-w-2xl text-xs leading-5 text-[#586970]">{stepIndex === 0 ? 'We will show only the settings that matter for this type of insurance.' : 'Keep it simple for customers while giving your underwriting team full control.'}</p>
        {stepIndex === 0 && <section className="mt-7 space-y-5"><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold text-[#5e7774]">Product name<input value={productName} onChange={(event) => { setProductName(event.target.value); setSaved(false) }} className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm outline-none focus:border-[#74bbae]"/></label><label className="text-xs font-semibold text-[#5e7774]">Product code<input value={productCode} onChange={(event) => { setProductCode(event.target.value.toUpperCase().replace(/\s/g, '-')); setSaved(false) }} placeholder="e.g. MC-STD-001" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm uppercase outline-none focus:border-[#74bbae]"/><span className="mt-1 block text-[10px] font-normal text-[#91a5a2]">Stable identifier used by API and partner channels.</span></label></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold text-[#5e7774]">Version<input value={version} onChange={event => setVersion(event.target.value)} placeholder="1.0" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><label className="text-xs font-semibold text-[#5e7774]">Effective date<input type="date" value={effectiveDate} onChange={event => setEffectiveDate(event.target.value)} className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label></div><label className="mt-4 block text-xs font-semibold text-[#5e7774]">Change note<input value={changeNote} onChange={event => setChangeNote(event.target.value)} placeholder="What changed in this version?" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><p className="mt-2 text-[10px] text-[#91a5a2]">A product code and version keep issued policies, API integrations, and renewals traceable.</p></div><div className="rounded-md border border-[#B9C0C2] bg-[#f5fbf9] p-5"><div><h3 className="text-sm font-semibold">How will this product be distributed?</h3><p className="mt-1 text-xs leading-5 text-[#586970]">Choose the delivery method separately from pricing. This controls how banks and third parties access quotes and policies.</p></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><button onClick={() => setDeliveryMethod('Embedded widget')} className={`rounded-xl border p-4 text-left ${deliveryMethod === 'Embedded widget' ? 'border-[#70b9aa] bg-white ring-2 ring-[#d9eee8]' : 'border-[#dfe9e7] bg-white/70'}`}><p className="text-xs font-semibold">Embedded widget</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">A branded quote form partners embed in their website or app. Best when you want a ready-made customer experience.</p><span className="mt-3 inline-block rounded-full bg-[#e8f5f1] px-2 py-1 text-[9px] font-semibold text-[#00392F]">No integration build required</span></button><button onClick={() => setDeliveryMethod('Bank / partner API')} className={`rounded-xl border p-4 text-left ${deliveryMethod === 'Bank / partner API' ? 'border-[#70b9aa] bg-white ring-2 ring-[#d9eee8]' : 'border-[#dfe9e7] bg-white/70'}`}><p className="text-xs font-semibold">Bank / partner API</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">A bank or partner builds its own experience using secure quote and policy endpoints.</p><span className="mt-3 inline-block rounded-full bg-[#eef3f1] px-2 py-1 text-[9px] font-semibold text-[#52736e]">Requires API credentials and webhooks</span></button></div><div className="mt-3 rounded-lg bg-white/75 p-3 text-[10px] leading-4 text-[#52736e]"><strong>Selected channel:</strong> {deliveryMethod}. Pricing rules stay the same; only the distribution and integration setup changes.</div></div><div className="grid gap-3 sm:grid-cols-2">{productTypes.map((type) => <button key={type.name} onClick={() => selectProductType(type.name)} className={`rounded-md border p-5 text-left ${productType === type.name ? 'border-[#70b9aa] bg-[#eaf7f3] ring-2 ring-[#d9eee8]' : 'border-[#dfe9e7] bg-white'}`}><div className="flex items-center justify-between"><h3 className="text-sm font-semibold">{type.name}</h3>{productType === type.name && <Check size={16} className="text-[#00392F]"/>}</div><p className="mt-2 text-xs leading-5 text-[#586970]">{type.description}</p><p className="mt-3 text-[10px] font-medium text-[#00392F]">{type.example}</p></button>)}</div><NextButton onClick={() => setStep(currentSteps[1])} label="Continue to coverages"/></section>}
        {stepIndex === 1 && <section className="mt-7 space-y-5"><div className="rounded-md border border-[#B9C0C2] bg-[#E7FDF6] p-4"><p className="text-[10px] font-bold uppercase tracking-[.14em] text-[#00392F]">Marine cargo cover framework</p><h3 className="mt-1 text-sm font-semibold text-[#060C0F]">Choose the Institute Cargo Clause that defines the protection</h3><p className="mt-1 text-[11px] leading-5 text-[#586970]">Start with a standard marine wording, then add cargo-specific extensions only when the insurer’s underwriting rules support them.</p><div className="mt-3 grid gap-2 sm:grid-cols-3"><button onClick={() => setCoverages(current => current.map(cover => cover.id === 'damage' ? { ...cover, name: 'Institute Cargo Clauses (A) - All Risks', description: 'All risks of physical loss or damage to the insured cargo, subject to exclusions and conditions.' } : cover))} className="rounded-lg border border-[#00392F] bg-white p-3 text-left"><p className="text-xs font-semibold text-[#00392F]">ICC (A)</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">All Risks</p></button><button onClick={() => setCoverages(current => current.map(cover => cover.id === 'damage' ? { ...cover, name: 'Institute Cargo Clauses (B) - Named Risks', description: 'Loss or damage caused by listed insured perils under the selected marine cargo wording.' } : cover))} className="rounded-lg border border-[#B9C0C2] bg-white p-3 text-left"><p className="text-xs font-semibold text-[#060C0F]">ICC (B)</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">Named Risks</p></button><button onClick={() => setCoverages(current => current.map(cover => cover.id === 'damage' ? { ...cover, name: 'Institute Cargo Clauses (C) - Basic Cover', description: 'Basic named-peril cargo protection for the risks listed in the policy wording.' } : cover))} className="rounded-lg border border-[#B9C0C2] bg-white p-3 text-left"><p className="text-xs font-semibold text-[#060C0F]">ICC (C)</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">Basic Cover</p></button></div><p className="mt-3 text-[10px] text-[#586970]">You can refine the selected clause cover below with limits, deductibles, exclusions, and extensions.</p></div><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><div className="mt-7 space-y-3">{coverages.map((coverage) => <div key={coverage.id} className={`flex items-center gap-3 rounded-md border bg-white p-4 ${coverage.enabled ? 'border-[#a9d4c9]' : 'border-[#dfe9e7]'}`}><button onClick={() => updateCoverage(coverage.id, !coverage.enabled)} className={`flex h-6 w-10 items-center rounded-full p-1 ${coverage.enabled ? 'justify-end bg-[#00392F]' : 'bg-[#d7e5e1]'}`}><span className="size-4 rounded-full bg-white"/></button><div className="flex-1"><h3 className="text-sm font-semibold">{coverage.name}</h3><p className="mt-1 text-xs text-[#586970]">{coverage.description}</p><p className="mt-2 text-[10px] font-medium text-[#00392F]">{coverage.pricingMethod === 'manual' ? 'Manual price' : coverage.pricingMethod === 'rate' ? `Rate on ${pricingConfig.previewLabel.toLowerCase()}` : coverage.pricingMethod === 'flat' ? 'Fixed amount' : coverage.pricingMethod === 'per-unit' ? 'Per unit' : coverage.pricingMethod === 'percent' ? 'Percentage of base' : 'Included in base price'}</p></div><button onClick={() => openCoverageEditor(coverage)} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-[10px] font-semibold text-[#00392F]">Edit cover</button></div>)}<button onClick={addCoverage} className="flex w-full items-center justify-center gap-2 rounded-md border border-dashed border-[#9ccbc0] bg-[#f8fcfb] p-4 text-xs font-semibold text-[#00392F]"><Plus size={15}/> Add a cover</button></div></div><NextButton onClick={() => setStep(currentSteps[2])} label="Continue to limits"/></section>}
        {stepIndex === 2 && <section className="mt-7 space-y-5"><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><h3 className="text-sm font-semibold">{limitConfig.title}</h3><p className="mt-1 text-xs leading-5 text-[#586970]">{limitConfig.helper}</p><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label={limitConfig.limitLabel} value={limit} onChange={setLimit} suffix={limitConfig.unit}/><Field label={limitConfig.deductibleLabel} value={deductible} onChange={setDeductible} suffix={limitConfig.unit}/></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{limitConfig.extra.map((label) => <label key={label} className="text-xs font-semibold text-[#5e7774]">{label}<input placeholder={`Optional ${label.toLowerCase()}`} className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-2.5 text-xs"/></label>)}</div></div><div className="rounded-md border border-[#B9C0C2] bg-[#eaf7f3] p-5"><p className="text-xs font-semibold text-[#00392F]">Customer-facing rule</p><p className="mt-2 text-xs leading-5 text-[#52736e]">This product accepts up to {Number(limit || 0).toLocaleString()} {limitConfig.unit} and the customer contributes {Number(deductible || 0).toLocaleString()} {limitConfig.unit} before the product responds.</p></div><NextButton onClick={() => setStep(currentSteps[3])} label="Continue to pricing"/></section>}
        {stepIndex === 3 && <section className="mt-7 space-y-5"><div className="grid gap-3 sm:grid-cols-2"><Choice label="Charge premium by" value={pricingBasis} options={pricingConfig.options} onChange={setPricingBasis}/><Choice label="Currency" value={currency} options={['LYD', 'USD', 'EUR']} onChange={setCurrency}/></div><div className="rounded-md border border-[#b9d9d2] bg-[#f5fbf9] p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-[#00392F]">Recommended for {productType}</p><p className="mt-1 text-xs leading-5 text-[#52736e]">{productType === 'Marine cargo' ? 'Start with cargo value pricing: apply a simple rate per shipment value, then add optional port, war-risk, or survey fees.' : productType === 'Motor fleet' ? 'Start with per-vehicle pricing and add separate rates for third-party liability and own damage.' : productType === 'Property' ? 'Start with property-value pricing and use sub-limits for contents, stock, and business interruption.' : productType === 'SME package' ? 'Start with a package premium, then add turnover or location adjustments only where they improve accuracy.' : 'Start with a transparent contribution rate and define participant and fund fees separately.'}</p></div><button onClick={() => { setPricingMode('rate'); setPricingBasis(pricingConfig.basis) }} className="shrink-0 rounded-lg bg-[#00392F] px-3 py-2 text-[10px] font-semibold text-white">Use suggestion</button></div></div><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><p className="text-xs font-semibold">How should this product be priced?</p><p className="mt-1 text-xs text-[#586970]">Choose the method your underwriting team actually uses. You can change it later.</p><div className="mt-4 grid gap-2 sm:grid-cols-4">{[['rate','One rate','Same rate for every quote'],['tiers','Rate tiers','Different rates by value'],['formula','Formula','Rate plus loadings and fees'],['manual','Manual','Team sets the premium']].map(([value, label, help]) => <button key={value} onClick={() => setPricingMode(value as typeof pricingMode)} className={`rounded-xl border p-3 text-left ${pricingMode === value ? 'border-[#70b9aa] bg-[#eaf7f3]' : 'border-[#dfe9e7]'}`}><p className="text-xs font-semibold">{label}</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">{help}</p></button>)}</div><div className="mt-6 border-t border-[#eef3f1] pt-5"><p className="text-xs font-semibold">{pricingMode === 'manual' ? 'Manual quote settings' : pricingMode === 'tiers' ? 'Rate tiers' : pricingMode === 'formula' ? 'Formula inputs' : `${pricingBasis} pricing`}</p><p className="mt-1 text-xs text-[#586970]">{pricingConfig.help}</p>{pricingMode === 'manual' ? <div className="rounded-xl bg-[#F1F6F8] p-4 text-xs leading-5 text-[#52736e]">No automatic premium is calculated. Your team will enter or approve the final premium for each quote. Set the currency and optional minimum below for guidance.</div> : pricingMode === 'tiers' ? <div className="space-y-2">{tierRows.map((row, index) => <div key={index} className="grid grid-cols-[1fr_110px_auto] gap-2"><input value={row[0]} onChange={e => setTierRows(tierRows.map((item, i) => i === index ? [e.target.value, item[1]] : item))} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-xs" placeholder="Value range"/><input value={row[1]} onChange={e => setTierRows(tierRows.map((item, i) => i === index ? [item[0], e.target.value] : item))} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-xs" placeholder="Rate"/><button onClick={() => setTierRows(tierRows.filter((_, i) => i !== index))} className="px-2 text-xs text-[#b05c57]">Remove</button></div>)}<button onClick={() => setTierRows([...tierRows, ['New range', baseRate]])} className="text-xs font-semibold text-[#00392F]">+ Add pricing tier</button></div> : <div className="grid gap-4 sm:grid-cols-2"><Field label={pricingConfig.inputLabel} value={baseRate} onChange={setBaseRate} suffix={pricingBasis.includes('value') ? '%' : currency}/>{pricingMode === 'formula' && <Field label="Risk loading" value={loading} onChange={setLoading} suffix="%"/>}<Field label="Minimum premium" value={minimumPremium} onChange={setMinimumPremium} suffix={currency}/></div>}<div className="mt-4 grid gap-4 sm:grid-cols-3"><Field label="Service / admin fee" value={serviceFee} onChange={setServiceFee} suffix="%"/><Field label="Tax / levy" value={tax} onChange={setTax} suffix="%"/><Field label="Currency" value={currency} onChange={setCurrency} suffix=""/></div><div className="mt-5 rounded-xl border border-[#dfe9e7] bg-[#fbfdfc] p-4"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold">Libya fee components</p><p className="mt-1 text-[10px] text-[#586970]">Keep regulatory and underwriting charges visible as separate components.</p></div><select value={feeMode} onChange={e => setFeeMode(e.target.value as typeof feeMode)} className="rounded-lg border border-[#dfe9e7] px-2 py-2 text-[10px]"><option value="percentage">Percentage</option><option value="fixed">Fixed {currency}</option></select></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="LISA fee" value={lisaFee} onChange={setLisaFee} suffix={feeMode === 'percentage' ? '%' : currency}/><Field label="Underwriting fee" value={underwritingFee} onChange={setUnderwritingFee} suffix={feeMode === 'percentage' ? '%' : currency}/></div><div className="mt-3 rounded-lg bg-[#eaf7f3] p-3 text-[10px] leading-4 text-[#52736e]">The quote preview adds {feeMode === 'percentage' ? `${lisaFee || 0}% LISA` : `${lisaFee || 0} ${currency} LISA`} and {feeMode === 'percentage' ? `${underwritingFee || 0}% underwriting` : `${underwritingFee || 0} ${currency} underwriting`} as separate line items.</div></div></div><div className="mt-5 rounded-xl bg-[#F1F6F8] p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#00392F]">Optional pricing rules</p><div className="mt-3 grid gap-2 text-xs text-[#5e7774]"><label><input type="checkbox" defaultChecked className="mr-2"/> Add a higher rate for high-risk cargo</label><label><input type="checkbox" className="mr-2"/> Add port or border surcharge</label><label><input type="checkbox" className="mr-2"/> Add broker commission separately</label></div></div></div><NextButton onClick={() => setStep(currentSteps[4])} label="Continue to conditions"/></section>}
        {stepIndex === 5 && <section className="mt-7 space-y-5"><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><h3 className="text-sm font-semibold">What the customer sees vs. what the policy contains</h3><p className="mt-1 text-xs leading-5 text-[#586970]">Keep the short quote explanation separate from binding policy wording and collected schedule data. This prevents partner channels from displaying internal or legal text in the wrong place.</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="rounded-xl border border-[#B9C0C2] bg-[#f5fbf9] p-3"><p className="text-[10px] font-bold uppercase tracking-[.1em] text-[#00392F]">1. Quote summary</p><p className="mt-1 text-[10px] leading-4 text-[#52736e]">Plain-language description shown to the customer before purchase.</p></div><div className="rounded-xl border border-[#B9C0C2] bg-[#f5fbf9] p-3"><p className="text-[10px] font-bold uppercase tracking-[.1em] text-[#00392F]">2. Policy terms</p><p className="mt-1 text-[10px] leading-4 text-[#52736e]">Binding wording printed in the policy schedule and documents.</p></div><div className="rounded-xl border border-[#B9C0C2] bg-[#f5fbf9] p-3"><p className="text-[10px] font-bold uppercase tracking-[.1em] text-[#00392F]">3. Schedule data</p><p className="mt-1 text-[10px] leading-4 text-[#52736e]">Answers collected from the customer and inserted into the policy.</p></div></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold text-[#5e7774]">Insurer display name<input value={insurerName} onChange={e => setInsurerName(e.target.value)} placeholder="e.g. United Insurance Company" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><label className="text-xs font-semibold text-[#5e7774]">Logo URL<input value={logoUrl} onChange={e => setLogoUrl(e.target.value)} placeholder="https://.../logo.png" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold text-[#5e7774]">Quote summary — Arabic<textarea value={arabicWording} onChange={e => setArabicWording(e.target.value)} rows={3} dir="rtl" placeholder="اكتب وصفاً مختصراً للتغطية يظهر قبل إصدار الوثيقة" className="mt-2 w-full resize-none rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/><span className="mt-1 block text-[10px] font-normal text-[#91a5a2]">Shown on the quote screen. Do not enter exclusions or legal clauses here.</span></label><label className="text-xs font-semibold text-[#5e7774]">Quote summary — English<textarea value={englishWording} onChange={e => setEnglishWording(e.target.value)} rows={3} placeholder="Summarise the protection in customer-friendly language." className="mt-2 w-full resize-none rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/><span className="mt-1 block text-[10px] font-normal text-[#91a5a2]">Shown on the quote screen. Keep it short and easy to understand.</span></label><label className="sm:col-span-2 text-xs font-semibold text-[#5e7774]">Binding policy terms<textarea value={policyTerms} onChange={e => setPolicyTerms(e.target.value)} rows={5} placeholder="Enter the approved wording, exclusions, warranties, and claims obligations printed in the policy." className="mt-2 w-full resize-none rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/><span className="mt-1 block text-[10px] font-normal text-[#91a5a2]">Printed in the policy document. Use approved legal wording; this is separate from the quote summary.</span></label></div><div className="mt-4 rounded-xl bg-[#F1F6F8] p-4"><p className="text-xs font-semibold">Policy schedule data</p><p className="mt-1 text-[10px] text-[#586970]">Select the data that must be collected and printed on the issued policy.</p><div className="mt-3 grid gap-2 sm:grid-cols-3">{policyFieldPresets[productType].map(field => <label key={field} className="flex items-center gap-2 rounded-lg border border-[#dfe9e7] bg-white p-2.5 text-[10px]"><input type="checkbox" checked={policyFields.includes(field)} onChange={e => setPolicyFields(e.target.checked ? [...policyFields, field] : policyFields.filter(item => item !== field))}/>{field}</label>)}</div></div><label className="flex items-center gap-3 rounded-lg border border-[#dfe9e7] p-3 text-xs"><input type="checkbox" checked={partnerBranding} onChange={e => setPartnerBranding(e.target.checked)}/> Allow approved bank or partner branding alongside the insurer logo</label></div><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><h3 className="text-sm font-semibold">Quote questions</h3><p className="mt-1 text-xs leading-5 text-[#586970]">Ask only what is needed to price and underwrite this {productType.toLowerCase()} product.</p><div className="mt-4 space-y-2">{questions.map((question, index) => <div key={`${question}-${index}`} className="flex items-center gap-2"><input value={question} onChange={e => setQuestions(questions.map((item, i) => i === index ? e.target.value : item))} className="min-w-0 flex-1 rounded-lg border border-[#dfe9e7] px-3 py-2.5 text-xs"/><button onClick={() => setQuestions(questions.filter((_, i) => i !== index))} className="px-2 text-xs text-[#b05c57]">Remove</button></div>)}</div><button onClick={() => setQuestions([...questions, 'New underwriting question'])} className="mt-3 rounded-lg border border-[#b9d9d2] px-3 py-2 text-xs font-semibold text-[#00392F]">+ Add question</button></div><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><h3 className="text-sm font-semibold">When should a quote be referred?</h3><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Refer above this insured value" value={referralThreshold} onChange={setReferralThreshold} suffix="LYD"/><label className="flex items-center gap-3 rounded-lg border border-[#dfe9e7] p-3 text-xs"><input type="checkbox" checked={underwritingRequired} onChange={e => setUnderwritingRequired(e.target.checked)}/> Require underwriting review for every quote</label></div></div><NextButton onClick={() => setStep(currentSteps[6])} label="Continue to preview"/></section>}{stepIndex === 3 && productType === 'Marine cargo' && <div className="rounded-md border border-[#e5d9c7] bg-[#fffaf2] p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-[#855d20]">Cargo risk pricing rules</p><p className="mt-1 text-xs leading-5 text-[#806d51]">High-risk cargo usually means dangerous goods, high-theft or attractive goods, fragile or temperature-controlled goods, pharmaceuticals, electronics, sanctioned or restricted goods, unusual routes, poor packing, or extended port storage. Add a loading or referral rule instead of hiding it in the base rate.</p></div><button onClick={() => setRiskRules([...riskRules, { name: 'New risk rule', trigger: '', adjustment: '0', unit: 'percent', enabled: false }])} className="shrink-0 rounded-lg border border-[#d9bd8d] px-3 py-2 text-[10px] font-semibold text-[#855d20]">+ Add rule</button></div><div className="mt-4 space-y-2">{riskRules.map((rule, index) => <div key={`${rule.name}-${index}`} className="rounded-xl border border-[#eadfcf] bg-white p-3"><div className="flex items-start gap-3"><div className="flex-1"><label className="flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={rule.enabled} onChange={e => setRiskRules(riskRules.map((item, i) => i === index ? { ...item, enabled: e.target.checked } : item))}/>{rule.name}</label><p className="mt-1 text-[10px] leading-4 text-[#806d51]">If: {rule.trigger || 'Define the trigger for this rule'}</p><p className="mt-1 text-[10px] font-medium text-[#855d20]">Adjustment: +{rule.adjustment} {rule.unit}</p></div><button onClick={() => setEditingRiskRule(editingRiskRule === index ? null : index)} className="rounded-lg border border-[#eadfcf] px-3 py-2 text-[10px] font-semibold text-[#855d20]">{editingRiskRule === index ? 'Close' : 'Edit'}</button></div>{editingRiskRule === index && <div className="mt-3 grid gap-2 border-t border-[#f1e7d8] pt-3 sm:grid-cols-[1fr_1.5fr_110px_110px]"><input value={rule.name} onChange={e => setRiskRules(riskRules.map((item, i) => i === index ? { ...item, name: e.target.value } : item))} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-xs" placeholder="Rule name"/><input value={rule.trigger} onChange={e => setRiskRules(riskRules.map((item, i) => i === index ? { ...item, trigger: e.target.value } : item))} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-xs" placeholder="When does it apply?"/><input value={rule.adjustment} onChange={e => setRiskRules(riskRules.map((item, i) => i === index ? { ...item, adjustment: e.target.value } : item))} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-xs" placeholder="Amount"/><select value={rule.unit} onChange={e => setRiskRules(riskRules.map((item, i) => i === index ? { ...item, unit: e.target.value } : item))} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-xs"><option value="percent">percent</option><option value="rate points">rate points</option><option value="fixed LYD">fixed LYD</option><option value="referral">refer to underwriter</option></select></div>}</div>)}</div></div>}{stepIndex === 4 && <section className="mt-7 space-y-5"><div className="rounded-md border border-[#B9C0C2] bg-white p-5"><h3 className="text-sm font-semibold">{conditionPresets[productType].title}</h3><p className="mt-1 text-xs leading-5 text-[#586970]">{conditionPresets[productType].helper}</p></div><div className="space-y-3">{conditionSections.map((condition, index) => <div key={`${condition.title}-${index}`} className="flex items-center gap-4 rounded-md border border-[#dfe9e7] bg-white p-5"><div className="flex size-8 items-center justify-center rounded-full bg-[#e8f5f1] text-sm font-semibold text-[#00392F]">{index + 1}</div><div className="flex-1"><h3 className="text-sm font-semibold">{condition.title}</h3><p className="mt-1 text-xs leading-5 text-[#586970]">{condition.text}</p></div><button onClick={() => setConditionDraft(condition)} className="rounded-lg border border-[#dfe9e7] px-3 py-2 text-[10px] font-semibold text-[#00392F]">Edit</button></div>)}<button onClick={() => setConditionDraft({ title: 'New policy section', text: '' })} className="flex w-full items-center justify-center gap-2 rounded-md border border-dashed border-[#9ccbc0] bg-[#f8fcfb] p-4 text-xs font-semibold text-[#00392F]"><Plus size={15}/> Add policy section</button></div><NextButton onClick={() => setStep(currentSteps[6])} label="Continue to preview"/></section>}
        {stepIndex === 6 && deliveryMethod === 'Embedded widget' && <section className="mt-7 rounded-md border border-[#dfe9e7] bg-white p-5 sm:p-8"><div className="mx-auto max-w-md rounded-md border border-[#dfe9e7] p-6"><div className="flex items-center justify-between gap-3"><div>{logoUrl ? <img src={logoUrl} alt={`${insurerName || 'Insurer'} logo`} className="h-8 max-w-[120px] object-contain"/> : <div className="flex h-8 items-center rounded-lg bg-[#e8f5f1] px-3 text-[10px] font-bold text-[#00392F]">{insurerName || 'Your insurer logo'}</div>}</div><p className="text-[10px] font-bold uppercase tracking-[.14em] text-[#00392F]">Customer quote preview</p></div><h3 className="mt-4 text-xl font-semibold">{productName}</h3><p className="mt-1 text-xs text-[#586970]">{selectedType.description}</p><div className="mt-5 rounded-xl border border-[#B9C0C2] bg-[#F1F6F8] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[9px] font-bold uppercase tracking-[.14em] text-[#00392F]">Shipment risk check</p><p className="mt-1 text-xs font-semibold text-[#060C0F]">{detectedHighRisk ? 'Additional underwriting review required' : 'Standard shipment path'}</p></div><span className={`rounded-full px-2.5 py-1 text-[9px] font-bold ${detectedHighRisk ? 'bg-[#FFF1D6] text-[#8A5A00]' : 'bg-[#E7FDF6] text-[#23733F]'}`}>{detectedHighRisk ? 'Review' : 'Clear'}</span></div><p className="mt-2 text-[10px] leading-4 text-[#586970]">This is a decision preview, not a mysterious score. The product checks the cargo class, route profile, and port storage period before applying any configured loading.</p><div className="mt-3 grid gap-2 sm:grid-cols-3"><div className="rounded-lg bg-white p-2.5"><p className="text-[9px] uppercase tracking-[.08em] text-[#586970]">Cargo</p><p className="mt-1 text-[10px] font-semibold text-[#060C0F]">{cargoClass}</p><p className="mt-1 text-[9px] text-[#586970]">{['Dangerous goods', 'Electronics', 'Pharmaceuticals', 'Temperature-controlled', 'High-theft goods'].includes(cargoClass) ? 'Loading may apply' : 'No cargo trigger'}</p></div><div className="rounded-lg bg-white p-2.5"><p className="text-[9px] uppercase tracking-[.08em] text-[#586970]">Route</p><p className="mt-1 text-[10px] font-semibold text-[#060C0F]">{routeProfile}</p><p className="mt-1 text-[9px] text-[#586970]">{routeProfile === 'High-risk / war-risk route' ? 'Route loading may apply' : 'Approved route path'}</p></div><div className="rounded-lg bg-white p-2.5"><p className="text-[9px] uppercase tracking-[.08em] text-[#586970]">Port storage</p><p className="mt-1 text-[10px] font-semibold text-[#060C0F]">{storageDays || '0'} days</p><p className="mt-1 text-[9px] text-[#586970]">{Number(storageDays) > 7 ? 'Storage loading may apply' : 'Within standard period'}</p></div></div>{detectedRiskTypes.length > 0 ? <div className="mt-3 rounded-lg border border-[#F1D9A6] bg-[#FFF8E8] p-3"><p className="text-[10px] font-semibold text-[#8A5A00]">Triggered rules: {detectedRiskTypes.join(' · ')}</p><p className="mt-1 text-[10px] leading-4 text-[#8A5A00]">Configured loading currently added: {activeRiskRate || activeRiskPercent ? `${activeRiskRate} rate points${activeRiskPercent ? ` + ${activeRiskPercent}%` : ''}` : 'No loading configured yet'}.</p></div> : <p className="mt-3 text-[10px] font-medium text-[#23733F]">No configured risk triggers detected for this sample shipment.</p>}</div><div className="mt-4 flex items-center gap-3 rounded-xl border border-[#dfe9e7] bg-[#f8fbfa] p-3"><div>{policyQr ? <img src={policyQr} alt="Policy verification QR preview" className="size-16"/> : <div className="size-16 rounded-lg bg-[#e8f5f1]"/>}</div><div><p className="text-[9px] font-bold uppercase tracking-[.12em] text-[#00392F]">Issued policy verification</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">The issued policy will carry a QR code that government and port officials can scan.</p></div></div><div className="mt-3 rounded-lg bg-[#F1F6F8] p-3"><p className="text-[9px] font-bold uppercase tracking-[.12em] text-[#91a5a2]">Distribution method</p><p className="mt-1 text-xs font-semibold text-[#00392F]">{deliveryMethod}</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">{deliveryMethod === 'Embedded widget' ? 'Partners receive a branded, ready-to-embed quote experience.' : 'Partners receive scoped API access for quotes, policies, and webhooks.'}</p></div>{(arabicWording || englishWording) && <div className="mt-4 rounded-xl bg-[#F1F6F8] p-3"><p className="text-[9px] font-bold uppercase tracking-[.12em] text-[#91a5a2]">Quote summary</p><p className="mt-1 text-xs leading-5 text-[#52736e]">{englishWording || arabicWording}</p></div>}{policyTerms && <div className="mt-3 rounded-xl border border-[#e5e9e7] bg-white p-3"><p className="text-[9px] font-bold uppercase tracking-[.12em] text-[#91a5a2]">Policy terms</p><p className="mt-1 whitespace-pre-line text-xs leading-5 text-[#52736e]">{policyTerms}</p></div>}{productType === 'Marine cargo' && <div className="mt-6 rounded-xl border border-[#dfe9e7] bg-[#f8fbfa] p-4"><p className="text-xs font-semibold text-[#00392F]">Shipment risk check</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">The quote flow catches risk before calculating the premium.</p><div className="mt-3 grid gap-2 sm:grid-cols-3"><select value={cargoClass} onChange={e => setCargoClass(e.target.value)} className="rounded-lg border border-[#dfe9e7] bg-white px-3 py-2 text-xs"><option>General cargo</option><option>Dangerous goods</option><option>Electronics</option><option>Pharmaceuticals</option><option>Temperature-controlled</option><option>High-theft goods</option></select><select value={routeProfile} onChange={e => setRouteProfile(e.target.value)} className="rounded-lg border border-[#dfe9e7] bg-white px-3 py-2 text-xs"><option>Standard approved route</option><option>High-risk / war-risk route</option></select><input value={storageDays} onChange={e => setStorageDays(e.target.value)} type="number" min="0" className="rounded-lg border border-[#dfe9e7] bg-white px-3 py-2 text-xs" placeholder="Port storage days"/></div>{detectedHighRisk ? <div className="mt-3 rounded-lg bg-[#fff4df] p-3 text-[10px] leading-4 text-[#855d20]"><strong>High risk detected.</strong> {detectedRiskTypes.join(' · ')}. {riskRules.some(rule => rule.enabled && matchingRiskRule(rule)) ? 'Configured loadings will be applied automatically.' : 'No active loading is configured, so this quote should be referred before publishing.'}</div> : <div className="mt-3 rounded-lg bg-[#eaf7f3] p-3 text-[10px] text-[#52736e]">Standard risk profile. No high-risk loading detected.</div>}</div>}<label className="mt-6 block text-xs font-semibold text-[#5e7774]">{pricingConfig.previewLabel}<input value={previewValue} onChange={(event) => setPreviewValue(event.target.value)} type="number" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><div className="mt-5 space-y-3">{enabledCoverages.map((coverage) => <div key={coverage.id} className="flex gap-2 text-xs"><Check size={14} className="text-[#3c9c81]"/>{coverage.name}</div>)}</div><div className="mt-6 flex items-end justify-between border-t border-[#e8efed] pt-5"><span className="text-xs text-[#586970]">Estimated premium</span><div className="text-right"><div className="space-y-1 text-[10px] text-[#586970]"><p>Base premium: {currency} {subtotal.toLocaleString()}</p><p>Risk loadings: {currency} {Math.round(riskAmount).toLocaleString()}</p><p>LISA fee: {currency} {Math.round(lisaAmount).toLocaleString()}</p><p>Underwriting: {currency} {Math.round(underwritingAmount).toLocaleString()}</p></div><span className="mt-2 block text-2xl font-semibold">{currency} {premium.toLocaleString()}</span></div></div><button className="mt-5 w-full rounded-lg bg-[#00392F] py-3 text-xs font-semibold text-white">Get a quote</button></div><NextButton onClick={() => { setStep(currentSteps[7]); if (canPublish) setSaved(true) }} label="Looks good, continue to publish"/></section>}
        {stepIndex === 6 && deliveryMethod === 'Bank / partner API' && <section className="print-policy mt-7 space-y-5"><div className="rounded-md border border-[#c7d8e8] bg-white p-5 sm:p-8"><header className="flex items-start justify-between gap-4 border-b border-[#e7edf2] pb-5"><div className="flex items-start gap-4">{logoUrl ? <img src={logoUrl} alt={`${insurerName || 'Insurer'} logo`} className="h-10 max-w-[140px] object-contain"/> : <div className="flex h-10 items-center rounded-lg bg-[#e9f1f7] px-3 text-[10px] font-bold text-[#2b5d83]">{insurerName || 'Insurer logo'}</div>}<div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#2b5d83]">API policy document preview</p><h2 className="mt-2 text-2xl font-semibold">{productName || 'Untitled product'}</h2><p className="mt-1 text-xs text-[#71869a]">Draft policy schedule generated from this product.</p></div></div><div className="text-right"><p className="text-[10px] uppercase tracking-[.12em] text-[#91a5a2]">Status</p><p className="mt-1 text-xs font-semibold text-[#2b5d83]">Draft preview</p></div></header><div className="mt-5 flex items-center gap-4 rounded-xl border border-[#dbe7ef] bg-[#f8fafc] p-3"><div className="shrink-0">{policyQr ? <img src={policyQr} alt="Policy verification QR code" className="size-[92px]"/> : <div className="size-[92px] rounded-lg bg-[#e7edf2]"/>}</div><div><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#2b5d83]">Verification QR</p><p className="mt-1 text-[10px] leading-4 text-[#71869a]">Generated when this policy is issued. Government parties and port officials can scan it to verify status, insured, product, and policy details.</p><p className="mt-1 break-all text-[9px] text-[#52687b]">{verificationUrl}</p></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{policyFields.map(field => <div key={field} className="rounded-lg border border-[#e7edf2] bg-[#f8fafc] p-3"><p className="text-[10px] text-[#71869a]">{field}</p><p className="mt-2 text-xs font-medium text-[#31475a]">{field === 'Commodity value' ? `${currency} ${Number(limit || 0).toLocaleString()}` : field === 'Effective dates' ? effectiveDate || 'To be entered at issue' : 'Collected from API request'}</p></div>)}</div><div className="mt-6 grid gap-4 sm:grid-cols-2"><div className="rounded-xl border border-[#e7edf2] p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#71869a]">Insured covers</p><div className="mt-3 space-y-3">{enabledCoverages.map(coverage => <div key={coverage.id} className="border-b border-[#eef2f5] pb-3 last:border-0 last:pb-0"><p className="text-xs font-semibold text-[#31475a]">{coverage.name}</p><p className="mt-1 text-[10px] leading-4 text-[#71869a]">{coverage.description}</p><p className="mt-1 text-[10px] text-[#52687b]">Limit: {coverage.limit || `${currency} ${Number(limit || 0).toLocaleString()}`} · Deductible: {coverage.deductible || `${currency} ${Number(deductible || 0).toLocaleString()}`}</p></div>)}</div></div><div className="rounded-xl border border-[#e7edf2] p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#71869a]">Conditions and warranties</p><div className="mt-3 space-y-3">{conditionSections.map(condition => <div key={condition.title}><p className="text-xs font-semibold text-[#31475a]">{condition.title}</p><p className="mt-1 text-[10px] leading-4 text-[#71869a]">{condition.text}</p></div>)}</div></div></div><div className="mt-6 rounded-xl border border-[#e7edf2] p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#71869a]">Premium and fees</p><div className="mt-3 grid grid-cols-2 gap-3 text-xs text-[#52687b]"><p>Base premium <strong className="block text-[#31475a]">{currency} {subtotal.toLocaleString()}</strong></p><p>Risk loading <strong className="block text-[#31475a]">{currency} {riskAmount.toLocaleString()}</strong></p><p>LISA fee <strong className="block text-[#31475a]">{currency} {Math.round(lisaAmount).toLocaleString()}</strong></p><p>Underwriting fee <strong className="block text-[#31475a]">{currency} {Math.round(underwritingAmount).toLocaleString()}</strong></p><p>Total premium <strong className="block text-[#2b5d83]">{currency} {premium.toLocaleString()}</strong></p></div></div><div className="mt-6 rounded-xl border border-[#e7edf2] p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#71869a]">Binding terms</p><p className="mt-2 whitespace-pre-line text-xs leading-5 text-[#52687b]">{policyTerms || 'Approved policy terms will appear here after they are added.'}</p></div><div className="mt-6 flex flex-wrap items-center justify-between gap-3 border-t border-[#e7edf2] pt-5"><p className="text-xs text-[#71869a]">API partners receive structured policy data and can request this document after approval.</p><button onClick={() => window.print()} className="rounded-lg bg-[#2b5d83] px-4 py-2.5 text-xs font-semibold text-white">Print / save PDF preview</button></div></div><NextButton onClick={() => { setStep(currentSteps[7]); if (canPublish) setSaved(true) }} label="Continue to publish"/></section>}{stepIndex === 7 && <section className="mt-7 space-y-5"><div className={`rounded-md border p-5 ${canPublish ? 'border-[#b9d9d2] bg-[#f5fbf9]' : 'border-[#efd5d2] bg-[#fff9f8]'}`}><div className="flex items-start gap-3"><div className={`flex size-8 items-center justify-center rounded-full ${canPublish ? 'bg-[#dff1ec] text-[#00392F]' : 'bg-[#f9e5e1] text-[#b05c57]'}`}>{canPublish ? '✓' : '!'}</div><div><h3 className="text-sm font-semibold">{canPublish ? 'Ready for approval' : 'Complete before publishing'}</h3><p className="mt-1 text-xs leading-5 text-[#586970]">{canPublish ? 'All required product, pricing, policy, and distribution controls are configured.' : 'The product stays a draft until the required controls are complete.'}</p>{!canPublish && <ul className="mt-3 space-y-1 text-xs text-[#b05c57]">{validationIssues.map(issue => <li key={issue}>• {issue}</li>)}</ul>}</div></div></div><div className="rounded-md border border-[#B9C0C2] bg-white p-6"><div className="flex items-start gap-3"><div className="rounded-full bg-[#e8f5f1] p-2 text-[#00392F]"><Check size={16}/></div><div><h3 className="text-sm font-semibold">Ready to publish {productName}</h3><p className="mt-2 text-xs leading-5 text-[#586970]">Your product has a product type, coverages, limits, pricing, conditions, and customer preview. You can still edit it after saving as a draft.</p></div></div><div className="mt-5 grid gap-4 border-t border-[#eef3f1] pt-5 sm:grid-cols-2"><Field label="Effective date" value={effectiveDate} onChange={setEffectiveDate} suffix=""/><p className="rounded-lg bg-[#F1F6F8] p-3 text-xs leading-5 text-[#52736e]">{underwritingRequired ? 'Underwriting review is required before activation.' : 'Quotes can be issued automatically within the configured limits.'}</p></div></div><button onClick={() => setSaved(true)} disabled={!productName.trim() || enabledCoverages.length === 0} className="mt-6 rounded-lg bg-[#00392F] px-4 py-3 text-xs font-semibold text-white">{saved ? 'Saved as draft' : 'Save product draft'}</button></section>}
      </div></main>
      <aside className="hidden border-l border-[#dbe8e4] bg-[#fbfdfc] p-4 lg:sticky lg:top-[68px] lg:col-start-3 lg:row-start-1 lg:block lg:h-[calc(100vh-68px)] lg:overflow-y-auto lg:self-start"><div className="flex items-center justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#00392F]">Live changes</p><p className="mt-1 text-xs font-semibold text-[#060C0F]">What insurers will receive</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">A compact live snapshot — not another step to complete.</p></div><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${saved ? 'bg-[#E7FDF6] text-[#23733F]' : 'bg-[#FFF1D6] text-[#8A5A00]'}`}>{saved ? 'Saved' : 'Draft'}</span></div><div className="mt-4 grid gap-2"><div className="rounded-lg border border-[#B9C0C2] bg-white p-3"><p className="text-[9px] font-bold uppercase tracking-[.1em] text-[#586970]">Product identity</p><p className="mt-2 text-xs font-semibold text-[#060C0F]">{productName || 'Untitled product'}</p><p className="mt-1 text-[10px] text-[#586970]">{productCode || 'No product code'} · v{version}</p><p className="mt-1 text-[10px] text-[#586970]">Effective {effectiveDate || 'date not set'}</p></div><div className="rounded-lg border border-[#B9C0C2] bg-white p-3"><div className="flex items-center justify-between"><p className="text-[9px] font-bold uppercase tracking-[.1em] text-[#586970]">Covers</p><span className="text-[10px] font-bold text-[#00392F]">{enabledCoverages.length} active</span></div><div className="mt-2 space-y-2">{enabledCoverages.length ? enabledCoverages.map(coverage => <div key={coverage.id} className="flex items-start justify-between gap-2"><p className="text-[10px] font-medium text-[#060C0F]">{coverage.name}</p><span className="text-[9px] text-[#586970]">{coverage.limit || 'Default limit'}</span></div>) : <p className="mt-2 text-[10px] text-[#F55754]">No covers enabled</p>}</div></div><div className="rounded-lg border border-[#B9C0C2] bg-white p-3"><p className="text-[9px] font-bold uppercase tracking-[.1em] text-[#586970]">Protection</p><div className="mt-2 grid grid-cols-2 gap-2"><div><p className="text-[9px] text-[#586970]">Limit</p><p className="mt-1 text-[10px] font-semibold text-[#060C0F]">{currency} {Number(limit || 0).toLocaleString()}</p></div><div><p className="text-[9px] text-[#586970]">Deductible</p><p className="mt-1 text-[10px] font-semibold text-[#060C0F]">{currency} {Number(deductible || 0).toLocaleString()}</p></div></div><p className="mt-2 text-[10px] text-[#586970]">{pricingMode === 'manual' ? 'Manual underwriting price' : `${pricingBasis} · ${selectedRate || 0}${feeMode === 'percentage' ? '%' : ` ${currency}`}`}</p></div><div className="rounded-lg border border-[#B9C0C2] bg-white p-3"><p className="text-[9px] font-bold uppercase tracking-[.1em] text-[#586970]">Distribution</p><p className="mt-2 text-xs font-semibold text-[#00392F]">{deliveryMethod}</p><p className="mt-1 text-[10px] leading-4 text-[#586970]">{deliveryMethod === 'Embedded widget' ? 'Branded quote experience for partners.' : 'Structured policy data and verified PDF output.'}</p></div><div className="rounded-lg border border-[#B9C0C2] bg-white p-3"><div className="flex items-center justify-between"><p className="text-[9px] font-bold uppercase tracking-[.1em] text-[#586970]">Policy output</p><button onClick={() => setStep(currentSteps[6])} className="text-[9px] font-bold text-[#00392F]">Open preview</button></div><p className="mt-2 text-[10px] text-[#060C0F]">{policyFields.length} schedule fields · {conditionSections.length} conditions</p><p className="mt-1 text-[10px] text-[#586970]">{questions.length} customer questions · QR verification enabled</p></div></div></aside>
      {conditionDraft && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#193332]/35 p-4"><div className="w-full max-w-lg rounded-md bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#00392F]">Policy section</p><h3 className="mt-2 text-xl font-semibold">Edit condition</h3><p className="mt-1 text-xs text-[#586970]">Write a clear rule insurers, partners, and customers can understand.</p></div><button onClick={() => setConditionDraft(null)} className="text-xs text-[#586970]">Close</button></div><div className="mt-6 space-y-4"><label className="text-xs font-semibold text-[#5e7774]">Section title<input value={conditionDraft.title} onChange={e => setConditionDraft({ ...conditionDraft, title: e.target.value })} className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><label className="text-xs font-semibold text-[#5e7774]">Policy wording<textarea value={conditionDraft.text} onChange={e => setConditionDraft({ ...conditionDraft, text: e.target.value })} rows={5} placeholder="Describe the rule, evidence required, or circumstance that applies." className="mt-2 w-full resize-none rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label></div><div className="mt-6 flex justify-end gap-2"><button onClick={() => setConditionDraft(null)} className="rounded-lg border border-[#dfe9e7] px-4 py-2.5 text-xs font-semibold text-[#5e7774]">Cancel</button><button onClick={() => { const existing = conditionSections.some(section => section.title === conditionDraft.title); setConditionSections(existing ? conditionSections.map(section => section.title === conditionDraft.title ? conditionDraft : section) : [...conditionSections, conditionDraft]); setConditionDraft(null) }} className="rounded-lg bg-[#00392F] px-4 py-2.5 text-xs font-semibold text-white">Save section</button></div></div></div>}
      {coverDraft && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#193332]/35 p-4"><div className="w-full max-w-xl rounded-md bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#00392F]">Cover settings</p><h3 className="mt-2 text-xl font-semibold">Edit {coverDraft.name || 'cover'}</h3><p className="mt-1 text-xs text-[#586970]">Define only the rules customers and underwriters need for this cover.</p></div><button onClick={() => { setCoverDraft(null) }} className="text-xs text-[#586970]">Close</button></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold text-[#5e7774]">Cover name<input value={coverDraft.name} onChange={e => setCoverDraft({ ...coverDraft, name: e.target.value })} className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><label className="text-xs font-semibold text-[#5e7774]">Default limit<input value={coverDraft.limit || ''} onChange={e => setCoverDraft({ ...coverDraft, limit: e.target.value })} placeholder="e.g. 1,000,000 LYD" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><label className="text-xs font-semibold text-[#5e7774]">Deductible<input value={coverDraft.deductible || ''} onChange={e => setCoverDraft({ ...coverDraft, deductible: e.target.value })} placeholder="e.g. 5,000 LYD or 0.5%" className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><label className="text-xs font-semibold text-[#5e7774]">How is this cover priced?<select value={coverDraft.pricingMethod || 'included'} onChange={e => setCoverDraft({ ...coverDraft, pricingMethod: e.target.value as Coverage['pricingMethod'] })} className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"><option value="included">Included in base price</option><option value="rate">Rate on insured value</option><option value="percent">Percentage of base premium</option><option value="flat">Fixed amount</option><option value="per-unit">Per vehicle / location / item</option><option value="manual">Manual underwriter price</option></select></label>{coverDraft.pricingMethod && coverDraft.pricingMethod !== 'included' && coverDraft.pricingMethod !== 'manual' && <label className="text-xs font-semibold text-[#5e7774]">{coverDraft.pricingMethod === 'rate' ? 'Rate' : coverDraft.pricingMethod === 'percent' ? 'Percentage' : coverDraft.pricingMethod === 'per-unit' ? 'Amount per unit' : 'Fixed amount'}<input value={coverDraft.pricingValue || ''} onChange={e => setCoverDraft({ ...coverDraft, pricingValue: e.target.value })} placeholder={coverDraft.pricingMethod === 'rate' ? 'e.g. 0.25' : 'Enter amount'} className="mt-2 w-full rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label>}<label className="text-xs font-semibold text-[#5e7774] sm:col-span-2">What does it cover?<textarea value={coverDraft.description} onChange={e => setCoverDraft({ ...coverDraft, description: e.target.value })} rows={3} className="mt-2 w-full resize-none rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label><label className="text-xs font-semibold text-[#5e7774] sm:col-span-2">Conditions and exclusions<textarea value={coverDraft.conditions || ''} onChange={e => setCoverDraft({ ...coverDraft, conditions: e.target.value })} rows={3} placeholder="e.g. Excludes unattended vehicle storage; requires packing evidence." className="mt-2 w-full resize-none rounded-lg border border-[#dfe9e7] px-3 py-3 text-sm"/></label></div><div className="mt-6 flex justify-end gap-2"><button onClick={() => { setCoverages(current => current.filter(item => item.id !== coverDraft.id)); setCoverDraft(null) }} className="mr-auto rounded-lg border border-[#efd5d2] px-4 py-2.5 text-xs font-semibold text-[#b05c57]">Remove cover</button><button onClick={() => { setCoverDraft(null) }} className="rounded-lg border border-[#dfe9e7] px-4 py-2.5 text-xs font-semibold text-[#5e7774]">Cancel</button><button onClick={saveCoverage} className="rounded-lg bg-[#00392F] px-4 py-2.5 text-xs font-semibold text-white">Save cover</button></div></div></div>}
      <aside className="hidden border-t border-[#dbe8e4] bg-white p-5 lg:block lg:border-l lg:border-t-0"><div className="flex items-center justify-between"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#91a5a2]">Live summary</p><span className="rounded-full bg-[#e8f5f1] px-2 py-1 text-[9px] font-semibold text-[#00392F]">Auto-saved draft</span></div><h3 className="mt-2 text-sm font-semibold">{productName}</h3><p className="mt-1 text-xs text-[#586970]">{productType}</p><div className="mt-6 space-y-4 text-xs"><Summary label="Coverages" value={`${enabledCoverages.length} selected`}/><Summary label="Limit" value={`${Number(limit || 0).toLocaleString()} LYD`}/><Summary label="Deductible" value={`${Number(deductible || 0).toLocaleString()} LYD`}/><Summary label="Pricing" value={`${pricingBasis}: ${baseRate} ${pricingBasis.includes('value') ? '%' : currency}`}/><div className="mt-4 border-t border-[#eef3f1] pt-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#91a5a2]">Policy schedule collects</p><p className="mt-2 text-xs leading-5 text-[#52736e]">{policyFields.join(' · ')}</p></div></div><div className="mt-6 border-t border-[#eef3f1] pt-5"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#91a5a2]">Readiness checklist</p><div className="mt-3 space-y-2 text-[10px]">{[['Product selected', Boolean(productName)], ['At least one cover', enabledCoverages.length > 0], ['Pricing configured', pricingMode === 'manual' || Boolean(baseRate)], ['Quote summary', Boolean(englishWording || arabicWording)], ['Binding policy terms', Boolean(policyTerms)], ['Effective date', Boolean(effectiveDate)]].map(([label, complete]) => <button key={String(label)} onClick={() => setStep(label === 'Product selected' ? currentSteps[0] : label === 'At least one cover' ? currentSteps[1] : label === 'Pricing configured' ? currentSteps[3] : (label === 'Quote summary' || label === 'Binding policy terms') ? currentSteps[5] : currentSteps[7])} className="flex w-full items-center gap-2 text-left"><span className={`flex size-4 items-center justify-center rounded-full text-[9px] ${complete ? 'bg-[#00392F] text-white' : 'border border-[#cbdcd7] text-[#9aaba8]'}`}>{complete ? '✓' : ''}</span><span className={complete ? 'text-[#52736e]' : 'text-[#586970]'}>{String(label)}</span></button>)}</div></div><div className="mt-7 rounded-xl bg-[#f3f8f6] p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#00392F]">Next best step</p><p className="mt-2 text-xs leading-5 text-[#66817c]">{stepIndex === 0 ? 'Choose a product type first.' : stepIndex === 6 ? 'Test the quote with different cargo values.' : 'Complete the next highlighted step.'}</p></div></aside>
    </div>
  </div>
  </div>
}

function NextButton({ onClick, label }: { onClick: () => void; label: string }) { return <button onClick={onClick} className="mt-2 inline-flex items-center gap-2 rounded-lg bg-[#00392F] px-4 py-3 text-xs font-semibold text-white">{label}<ChevronRight size={14}/></button> }
function Field({ label, value, onChange, suffix }: { label: string; value: string; onChange: (value: string) => void; suffix: string }) { return <label className="text-xs font-semibold text-[#5e7774]">{label}<div className="mt-2 flex overflow-hidden rounded-lg border border-[#dfe9e7]"><input value={value} onChange={(event) => onChange(event.target.value)} className="min-w-0 flex-1 px-3 py-3 text-sm outline-none"/><span className="bg-[#F1F6F8] px-3 py-3 text-[10px] text-[#586970]">{suffix}</span></div></label> }
function Choice({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { return <label className="text-xs font-semibold text-[#5e7774]">{label}<div className="relative mt-2"><select value={value} onChange={(event) => onChange(event.target.value)} className="w-full appearance-none rounded-lg border border-[#dfe9e7] bg-white px-3 py-3 text-sm outline-none">{options.map((option) => <option key={option}>{option}</option>)}</select><ChevronDown size={14} className="pointer-events-none absolute right-3 top-3.5 text-[#586970]"/></div></label> }
function Condition({ title, text }: { title: string; text: string }) { return <button className="flex w-full items-center gap-4 rounded-md border border-[#dfe9e7] bg-white p-5 text-left"><div className="flex size-8 items-center justify-center rounded-full bg-[#e8f5f1] text-[#00392F]"><Plus size={15}/></div><div className="flex-1"><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 text-xs text-[#586970]">{text}</p></div><ChevronRight size={16} className="text-[#b0c2be]"/></button> }
function Summary({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between border-b border-[#eef3f1] pb-3"><span className="text-[#586970]">{label}</span><span className="font-semibold">{value}</span></div> }
